# Các ví dụ code cho TechCorp trong ngành FinTech

```python
# Script này kết nối với API của TechCorp và xử lý dữ liệu giao dịch
import requests
import json

# API endpoint và headers
url = "https://api.techcorp.com/v1/transactions"
headers = {
    "Authorization": "Bearer YOUR_ACCESS_TOKEN",
    "Content-Type": "application/json"
}

# Lấy dữ liệu giao dịch
response = requests.get(url, headers=headers)
transactions = response.json()

# Xử lý và phân tích dữ liệu
for transaction in transactions:
    if transaction['amount'] > 1000:
        print(f"Giao dịch giá trị cao: {transaction['id']}")
```

```javascript
// Script này tích hợp dữ liệu giao dịch vào dashboard của TechCorp
